use std :: path :: Path ; use crate :: { Match , MatchResult } ; # [doc = " Truncates a key string for display purposes"] # [doc = ""] # [doc = " If the key length is 20 characters or less, returns it unchanged."] # [doc = " Otherwise, shows the first 13 characters and last 4 characters with \"...\" in"] # [doc = " between."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `key` - The key string to truncate"] # [doc = ""] # [doc = " # Returns"] # [doc = " * A truncated version of the key for safe display"] pub use forge_domain :: truncate_key ; use sha2 :: { Digest , Sha256 } ; use pretty_assertions :: assert_eq ; use serde_json :: json ; use super :: * ; # [doc = " Returns true if the Content-Type header indicates binary (non-text) content."] # [doc = ""] # [doc = " This utility helps detect binary content types commonly returned by HTTP"] # [doc = " responses. It's useful for tools that handle text content but need to detect"] # [doc = " and reject binary data."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `content_type` - The Content-Type header value (e.g., \"text/html\","] # [doc = "   \"application/octet-stream\")"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use forge_app::utils::is_binary_content_type;"] # [doc = ""] # [doc = " // Text content types are not binary"] # [doc = " assert!(!is_binary_content_type(\"text/html\"));"] # [doc = " assert!(!is_binary_content_type(\"application/json\"));"] # [doc = ""] # [doc = " // Binary content types are detected"] # [doc = " assert!(is_binary_content_type(\"image/png\"));"] # [doc = " assert!(is_binary_content_type(\"application/octet-stream\"));"] # [doc = " ```"] pub fn is_binary_content_type (content_type : & str) -> bool { let ct = content_type . to_lowercase () ; if ct . starts_with ("text/") || ct . contains ("json") || ct . contains ("xml") || ct . contains ("javascript") || ct . contains ("ecmascript") || ct . contains ("yaml") || ct . contains ("toml") || ct . contains ("csv") || ct . contains ("html") || ct . contains ("svg") || ct . contains ("markdown") || ct . is_empty () { return false ; } true }